import "array"

sal = float(v: v.salIndex)  // if your variable is string: float(v: string(v: v.salIndex))

data = from(bucket: "efd/autogen")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) =>
      r._measurement == "lsst.sal.Scheduler.logevent_observatoryStatus" and
      (r._field == "status" or r._field == "salIndex")
    )

  |> pivot(rowKey: ["_time"], columnKey: ["_field"], valueColumn: "_value")
  |> filter(fn: (r) => exists r.salIndex and exists r.status)
  |> filter(fn: (r) => r.salIndex == sal)
  |> keep(columns: ["_time", "status"])

  //Get elapsed time between state switches. This is however the time towards the previous switch. 
  //We however want the timespan towards the next switch
  //=> In the following we are shifting the "elapsed" column by one entry up.
  |> elapsed(unit: 1m)

  //1. Add row index
  |> map(fn: (r) => ({ r with rowIndex: 1 }))
  |> cumulativeSum(columns: ["rowIndex"])

//startingRow = array.from(rows: [{ rowIndex: 0, _time: now(), status: 0, elapsed: 0}])
//data_sr = union(tables: [startingRow, data])
//  |> sort(columns: ["rowIndex"])
//  |> yield(name: "custom-name")


// 2. Create the "shifted" table by increasing the index by 1
shifted_data = data

  |> map(fn: (r) => ({ r with rowIndex: r.rowIndex + 1 }))

// 3. Join the original and shifted tables on the index
join(tables: {curr: data, prev: shifted_data}, on: ["rowIndex"])
  |> map(fn: (r) => ({
      r with 
      original_value: r._value_curr,
      shifted_value: r._value_prev  // This is now the value from the previous row
  }))

  |> keep(columns: ["_time_prev", "status_prev", "elapsed_curr"])
  |> rename(columns: {_time_prev: "_time", status_prev: "status", elapsed_curr: "elapsed"})
  // Group according to observatory state
  |> group(columns: ["status"])
  // Sum the values in ellapsed
  |> sum(column: "elapsed")
  |> group()

